    sources:[...sovietSouthwesternCanonSources,{href:"https://pamyat-naroda.ru/heroes/pamyat-commander824/",label:"Pamyat Naroda — Muzychenko service cards, biography, awards, and captivity record"},{href:"https://pamyat-naroda.ru/warunit/id11276/",label:"Pamyat Naroda — Sixth Army first formation"},{href:"https://ru.wikisource.org/wiki/Сборник_боевых_документов/39/141",label:"Wikisource — Sixth Army Order No. 0073 signed by Muzychenko, 30 July 1941"},{href:"https://www.lineofdeparture.army.mil/Journals/Army-History/Archive/Spring-2025-Issue/Winning-Outnumbered/",label:"U.S. Army History — Sixth Army and front-level decisions at Brody–Dubno"}],
    categories:["Ivan Muzychenko","Soviet generals","Sixth Army","Battle of Uman","Soviet prisoners of war"],
    facts:[["Full name","Ivan Nikolaevich Muzychenko"],["Born","10 November 1901 · New Style"],["Birthplace","Rostov-on-Don"],["Service","Imperial Russian Army · Red Army"],["Rank","Lieutenant general · 4 June 1940"],["Principal command","Sixth Army · 26 July 1940–August 1941"],["Captured","6 August 1941 · Uman pocket"],["Condition at capture","Severely wounded in the left leg"],["Historical 1945 liberation","Does not occur as recorded"],["Later fate","Open"]]
