    sources:[...sovietSouthwesternCanonSources,{href:"https://pamyat-naroda.ru/warunit/12%20%D0%90/",label:"Pamyat Naroda — Twelfth Army formations, commanders, and active periods"},{href:"https://pamyat-naroda.ru/heroes/pamyat-commander956/",label:"Pamyat Naroda — Ponedelin service record and Twelfth Army command"},{href:"https://history.org.ua/JournALL/kraj/kraj_2011_2/7.pdf",label:"Ukrainian historical study — Twelfth Army frontier deployment and 1941 operations"},{href:"https://resource.history.org.ua/cgi-bin/eiu/history.exe?C21COM=S&I21DBN=EIU&P21DBN=EIU&S21STR=Umanska_oboronna_1941",label:"Encyclopedia of the History of Ukraine — Uman defensive operation"}],
    categories:["Twelfth Army","Red Army armies","Battle of Uman","Southwestern Front","Operation Barbarossa"],
    facts:[["Formation represented","First formation"],["Formed","1939"],["Active army","22 June–10 August 1941"],["Commander","Major General Pavel Ponedelin"],["Initial superior command","Southwestern Front"],["Transferred","Southern Front · late July 1941"],["Initial sector","Carpathian and Romanian frontier"],["Final battle","Battle of Uman"],["Commander captured","7 August 1941"],["Result","Destroyed"],["Second formation","Separate army formed 25 August 1941"]]
